  1	/* ============================================================
  2	   views/config.js — Configuration view
  3	   Section 4d of the MCP Server Dashboard SPA
  4	   Depends on: API, UI, escapeHtml, showLoading, showError
  5	   ============================================================ */
  6	
  7	/* ── Module-level state ──────────────────────────────────── */
  8	
  9	var configActiveTab = 'general';
 10	
 11	/* Dirty-tracking: keyed by tab name, true when the tab has unsaved changes */
 12	var configDirty = {
 13	  general: false,
 14	  personaModels: false,
 15	  modelRegistry: false
 16	};
 17	
 18	/* ── Entry point ─────────────────────────────────────────── */
 19	
 20	function renderConfig(app) {
 21	  showLoading(app);
 22	
 23	  Promise.all([
 24	    API.getConfig(),
 25	    API.getModels ? API.getModels() : Promise.resolve([]),
 26	    API.getPersonas ? API.getPersonas() : Promise.resolve([]),
 27	    API.getAssignments ? API.getAssignments() : Promise.resolve([])
 28	  ]).then(function (results) {
 29	    var config      = results[0];
 30	    var models      = results[1];
 31	    var personas    = results[2];
 32	    var assignments = results[3];
 33	
 34	    renderConfigPage(app, config, models, personas, assignments);
 35	  }).catch(function (err) {
 36	    showError(app, 'Failed to load configuration: ' + (err.message || String(err)));
 37	  });
 38	}
 39	
 40	/* ── Page scaffold ───────────────────────────────────────── */
 41	
 42	function renderConfigPage(app, config, models, personas, assignments) {
 43	  /* Reset dirty flags — fresh server data has just been loaded, so any stale
 44	     dirty state from a previous page visit is no longer meaningful. */
 45	  configDirty.general       = false;
 46	  configDirty.personaModels = false;
 47	  configDirty.modelRegistry = false;
 48	
 49	  /* Reset Model Registry local state so it re-initialises from fresh server data. */
 50	  mrModels    = null;
 51	  mrOriginal  = null;
 52	  mrEditingId = null;
 53	
 54	  /* Reset Persona Models local state so it re-initialises from fresh server data. */
 55	  pmModels      = null;
 56	  pmPersonas    = null;
 57	  pmAssignments = null;
 58	  pmOriginal    = null;
 59	  pmIsBuilding  = false;
 60	  pmCollapsed   = {};
 61	  pmReplaceOpen = false;
 62	
 63	  app.innerHTML =
 64	    '<div class="page-header"><h1>Configuration</h1></div>' +
 65	    '<div class="config-tabs" id="config-tab-bar">' +
 66	      '<button class="config-tab' + (configActiveTab === 'general'       ? ' active' : '') + '" data-tab="general">General</button>' +
 67	      '<button class="config-tab' + (configActiveTab === 'personaModels' ? ' active' : '') + '" data-tab="personaModels">Persona Models</button>' +
 68	      '<button class="config-tab' + (configActiveTab === 'modelRegistry' ? ' active' : '') + '" data-tab="modelRegistry">Model Registry</button>' +
 69	    '</div>' +
 70	    '<div id="config-tab-content"></div>';
 71	
 72	  /* Render active tab content */
 73	  renderConfigTabContent(config, models, personas, assignments);
 74	
 75	  /* Wire tab-bar clicks */
 76	  var tabBar = document.getElementById('config-tab-bar');
 77	  if (tabBar) {
 78	    tabBar.addEventListener('click', function (e) {
 79	      var btn = e.target.closest('button[data-tab]');
 80	      if (!btn) return;
 81	      var tab = btn.getAttribute('data-tab');
 82	      if (tab === configActiveTab) return;
 83	
 84	      /* Unsaved-changes guard */
 85	      if (configDirty[configActiveTab]) {
 86	        if (!confirm('You have unsaved changes. Discard them?')) {
 87	          return; /* Stay */
 88	        }
 89	        configDirty[configActiveTab] = false;
 90	        /* Reset Model Registry local state when discarding changes so a
 91	           fresh load occurs on the next visit. */
 92	        if (configActiveTab === 'modelRegistry') {
 93	          mrModels    = null;
 94	          mrOriginal  = null;
 95	          mrEditingId = null;
 96	        }
 97	        /* Reset Persona Models local state when discarding changes. */
 98	        if (configActiveTab === 'personaModels') {
 99	          pmModels      = null;
100	          pmPersonas    = null;
101	          pmAssignments = null;
102	          pmOriginal    = null;
103	          pmIsBuilding  = false;
104	          pmCollapsed   = {};
105	          pmReplaceOpen = false;
106	        }
107	      }
108	
109	      /* Update active tab state */
110	      configActiveTab = tab;
111	
112	      /* Update active class on buttons without re-rendering the full page */
113	      var allBtns = tabBar.querySelectorAll('.config-tab');
114	      allBtns.forEach(function (b) {
115	        b.classList.toggle('active', b.getAttribute('data-tab') === tab);
116	      });
117	
118	      /* Re-render only the tab content area */
119	      renderConfigTabContent(config, models, personas, assignments);
120	    });

121	  }
122	}
123	
124	/* ── Tab content dispatcher ──────────────────────────────── */
125	
126	function renderConfigTabContent(config, models, personas, assignments) {
127	  var contentEl = document.getElementById('config-tab-content');
128	  if (!contentEl) return;
129	
130	  if (configActiveTab === 'general') {
131	    contentEl.innerHTML = renderGeneralTab(config);
132	    wireGeneralTabEvents();
133	  } else if (configActiveTab === 'personaModels') {
134	    contentEl.innerHTML = renderPersonaModelsTab(models, personas, assignments);
135	    pmWireEvents(config, models, personas, assignments);
136	  } else if (configActiveTab === 'modelRegistry') {
137	    contentEl.innerHTML = renderModelRegistryTab(models);
138	    mrWireEvents();
139	  }
140	}
141	
142	/* ── General tab ─────────────────────────────────────────── */
143	
144	function renderGeneralTab(config) {
145	  return UI.card(null,
146	    '<form id="config-form">' +
147	      '<div class="form-group">' +
148	        '<label class="form-label" for="auto-handoff">' +
149	          '<input type="checkbox" id="auto-handoff" class="form-check" ' + (config.auto_handoff_enabled ? 'checked' : '') + '>' +
150	          ' Auto-handoff enabled' +
151	        '</label>' +
152	        '<p class="form-note">When enabled, the MCP server automatically chains work to the next agent in the workflow.</p>' +
153	      '</div>' +
154	      '<div class="form-group">' +
155	        '<label class="form-label" for="max-depth">Max handoff depth</label>' +
156	        '<input type="number" id="max-depth" class="form-control" min="1" value="' + escapeHtml(String(config.max_handoff_depth)) + '">' +
157	        '<p class="form-note">Maximum number of automatic agent handoffs before stopping.</p>' +
158	      '</div>' +
159	      '<div class="form-group">' +
160	        '<label class="form-label" for="capture-dialogues">' +
161	          '<input type="checkbox" id="capture-dialogues" class="form-check" ' + (config.capture_dialogues ? 'checked' : '') + '>' +
162	          ' Capture agent dialogues' +
163	        '</label>' +
164	        '<p class="form-note">When enabled, the orchestrator saves the full LLM conversation for each pipeline stage to the project\'s ledger as Markdown files. Changes take effect on the next orchestrator run.</p>' +
165	      '</div>' +
166	      '<div class="form-group">' +
167	        '<label class="form-label" for="auto-archive-days">Auto-archive after (days)</label>' +
168	        '<input type="number" id="auto-archive-days" class="form-control" min="0" step="1" value="' + escapeHtml(String(config.auto_archive_days != null ? config.auto_archive_days : 6)) + '">' +
169	        '<p class="form-note">Number of days after last update before a COMPLETE project is automatically archived. Set to 0 to disable auto-archiving.</p>' +
170	      '</div>' +
171	      '<div class="form-group">' +
172	        '<label class="form-label" for="ledger-root">Ledger root path</label>' +
173	        '<input type="text" id="ledger-root" class="form-control" readonly value="' + escapeHtml(config.ledger_root || '') + '">' +
174	        '<p class="form-note">Read-only. Changing this requires restarting the server with <code>--ledger-dir</code>.</p>' +
175	      '</div>' +
176	      '<button type="submit" class="btn btn-primary">Save</button>' +
177	      '<div id="config-msg"></div>' +
178	    '</form>',
179	    { style: 'max-width:560px' }
180	  );
181	}
182	
183	function wireGeneralTabEvents() {
184	  var form = document.getElementById('config-form');
185	  if (!form) return;
186	
187	  /* Mark tab dirty on any input change.
188	     Both 'change' and 'input' are intentional: checkboxes fire 'change'
189	     (not 'input'), while text/number inputs fire 'input' on each keystroke.
190	     Using both ensures all form control types are covered. */
191	  form.addEventListener('change', function () {
192	    configDirty.general = true;
193	  });
194	  form.addEventListener('input', function () {
195	    configDirty.general = true;
196	  });
197	
198	  form.addEventListener('submit', function (e) {
199	    e.preventDefault();
200	    var autoHandoff = document.getElementById('auto-handoff').checked;
201	    var maxDepth = parseInt(document.getElementById('max-depth').value, 10);
202	    if (isNaN(maxDepth) || maxDepth < 1) {
203	      showError(document.getElementById('config-msg'), 'Max handoff depth must be a positive integer.');
204	      return;
205	    }
206	    var captureDialogues = document.getElementById('capture-dialogues').checked;
207	    var autoArchiveDays = parseInt(document.getElementById('auto-archive-days').value, 10);
208	    if (isNaN(autoArchiveDays) || autoArchiveDays < 0) {
209	      showError(document.getElementById('config-msg'), 'Auto-archive days must be a non-negative integer.');
210	      return;
211	    }
212	    /* ledger_root intentionally omitted (read-only) */
213	    API.updateConfig({ auto_handoff_enabled: autoHandoff, max_handoff_depth: maxDepth, capture_dialogues: captureDialogues, auto_archive_days: autoArchiveDays })
214	      .then(function () {
215	        configDirty.general = false;
216	        document.getElementById('config-msg').innerHTML = '<p class="success-banner">Configuration saved.</p>';
217	      })
218	      .catch(function (err) {
219	        showError(document.getElementById('config-msg'), 'Save failed: ' + (err.message || String(err)));
220	      });
221	  });
222	}
223	
224	/* ── Persona Models tab ──────────────────────────────────── */
225	
226	/* Module-level state for Persona Models tab.
227	   pmModels:       working copy of model list (loaded from server, used for dropdowns).
228	   pmPersonas:     full persona list from GET /api/personas.
229	   pmAssignments:  working copy of assignments (default_model_uuid + persona_models).
230	   pmOriginal:     snapshot of assignments at load/save time for dirty comparison.
231	   pmIsBuilding:   true while a rebuild is in progress.
232	   pmCollapsed:    set of suite names the user has collapsed.
233	   pmReplaceOpen:  true when the Replace Model inline form is shown. */
