254	/** Deep-clone assignments object. */
255	function pmCloneAssignments(a) {
256	  if (!a) return { persona_models: {} };
257	  return {
258	    default_model_uuid: a.default_model_uuid,
259	    persona_models: Object.assign({}, a.persona_models || {})
260	  };
