263	/** Return true when working copy has unsaved changes vs snapshot. */
264	function pmHasChanges() {
265	  if (!pmAssignments || !pmOriginal) return false;
266	  if (pmAssignments.default_model_uuid !== pmOriginal.default_model_uuid) return true;
267	  var aPm = pmAssignments.persona_models || {};
268	  var oPm = pmOriginal.persona_models || {};
269	  var aKeys = Object.keys(aPm);
270	  var oKeys = Object.keys(oPm);

271	  if (aKeys.length !== oKeys.length) return true;
272	  for (var i = 0; i < aKeys.length; i++) {
273	    if (aPm[aKeys[i]] !== oPm[aKeys[i]]) return true;
274	  }
275	  return false;
276	}
