278	/** Resolve a model UUID to its display name. Returns null when not found. */
279	function pmModelName(uuid) {
280	  if (!uuid || !pmModels) return null;
281	  for (var i = 0; i < pmModels.length; i++) {
282	    if (pmModels[i].id === uuid) return pmModels[i].name;
283	  }
284	  return null;
285	}
