292	/** Build <option> elements for a model dropdown.
293	 *  If includeDefault is true, prepends a "Default" option with value ''. */
294	function pmBuildModelOptions(selectedUuid, includeDefault) {
295	  var opts = '';
296	  if (includeDefault) {
297	    opts += '<option value=""' + (!selectedUuid ? ' selected' : '') + '>Default</option>';
298	  }
299	  if (pmModels) {
300	    for (var i = 0; i < pmModels.length; i++) {
301	      var m = pmModels[i];
302	      var sel = (m.id === selectedUuid) ? ' selected' : '';
303	      opts += '<option value="' + escapeHtml(m.id) + '"' + sel + '>' + escapeHtml(m.name) + '</option>';
304	    }
305	  }
306	  return opts;
307	}
