718	/* ── API actions ─────────────────────────────────────────── */
719	
720	/** Save the current assignment working copy to PUT /api/model-assignments. */
721	function pmDoSave(config, models, personas, assignments) {
722	  var saveBtn = document.getElementById('pm-save-btn');
723	  var msgEl   = document.getElementById('pm-save-msg');
724	  if (saveBtn) saveBtn.disabled = true;
725	  if (msgEl)   msgEl.innerHTML  = '<span style="color:var(--color-text-muted);font-size:13px;">Saving…</span>';
726	
727	  var payload = {
728	    persona_models: pmAssignments ? (pmAssignments.persona_models || {}) : {}
729	  };
730	  if (pmAssignments && pmAssignments.default_model_uuid) {
731	    payload.default_model_uuid = pmAssignments.default_model_uuid;
732	  }
733	
734	  API.updateAssignments(payload)
735	    .then(function (result) {
736	      /* Update snapshot and mark saved state as stale (server returns stale: true) */
737	      pmOriginal = pmCloneAssignments(result || payload);
738	      if (pmAssignments) {
739	        if (result) {
740	          pmAssignments.stale             = result.stale;
741	          pmAssignments.default_model_uuid = result.default_model_uuid;
742	          pmAssignments.persona_models     = result.persona_models || {};
743	        }
744	      }
745	      configDirty.personaModels = false;
746	      pmRefreshTab(config, models, personas, assignments);
