 835	/** Derive a slug from a human-readable name. */
 836	function mrDeriveSlug(name) {
 837	  return (name || '')
 838	    .toLowerCase()
 839	    .replace(/\s+/g, '-')
 840	    .replace(/[^a-z0-9-]/g, '')
 841	    .replace(/-+/g, '-')
 842	    .replace(/^-|-$/g, '');
 843	}
 844	
 845	/** Validate a slug string.  Returns an error message or '' if valid. */
 846	function mrValidateSlug(slug) {
 847	  if (!slug) return 'Slug is required.';
 848	  if (slug === 'inherit') return 'The slug "inherit" is reserved.';
 849	  if (!MR_SLUG_REGEX.test(slug)) return 'Slug must be lowercase alphanumeric with hyphens (e.g. my-model).';
 850	  return '';
