551	/**
552	 * Spawns `node scripts/build-personas.js` in the workspace root, capturing
553	 * combined stdout+stderr output.
554	 *
555	 * Concurrency guard: returns 409 Conflict when a build is already in progress.
556	 * The `buildInProgress` flag is cleared in a `finally` block to handle
557	 * unexpected process errors.
558	 *
559	 * @param workspaceRoot - Absolute path to the workspace root (contains `scripts/`).
560	 */
561	export async function handleRebuildPersonas(workspaceRoot: string): Promise<{
562	  success: true;
563	  output: string;
564	} | {
565	  success: false;
566	  output: string;
567	  exitCode: number;
568	}> {
569	  if (buildInProgress) {
570	    throw new ApiError(
571	      'CONFLICT',
572	      'A persona build is already in progress. Please wait for it to complete.'
573	    );
574	  }
575	
576	  buildInProgress = true;
577	
578	  try {
579	    const output = await new Promise<{ output: string; exitCode: number }>(
580	      (resolve) => {
581	        const scriptPath = join(workspaceRoot, 'scripts', 'build-personas.js');
582	        const child = spawn('node', [scriptPath], {
583	          cwd: workspaceRoot,
584	          env: process.env,
585	        });
586	
587	        const chunks: string[] = [];
588	
589	        child.stdout.on('data', (chunk: Buffer) => {
590	          chunks.push(chunk.toString());
591	        });
592	
593	        child.stderr.on('data', (chunk: Buffer) => {
594	          chunks.push(chunk.toString());
595	        });
596	
597	        child.on('close', (code: number | null) => {
598	          resolve({ output: chunks.join(''), exitCode: code ?? 1 });
599	        });
600

601	        child.on('error', (err: Error) => {
602	          resolve({
603	            output: `Process error: ${err.message}`,
604	            exitCode: 1,
605	          });
606	        });
607	      }
608	    );
609	
610	    if (output.exitCode === 0) {
611	      return { success: true, output: output.output };
612	    } else {
613	      return { success: false, output: output.output, exitCode: output.exitCode };
614	    }
615	  } finally {
616	    buildInProgress = false;
617	  }
618	}
619	
620	/**
621	 * Exposed for testing purposes only — resets the module-level concurrency guard.
622	 * @internal
623	 */
624	export function _resetBuildInProgress(): void {
625	  buildInProgress = false;
626	}

